mapper.select:
SELECT * FROM import_batches
WHERE file_hash = #{fileHash} AND import_type = #{importType} AND period = #{period}
LIMIT 1

mapper.update:
UPDATE import_batches SET import_type=#{importType}, file_name=#{fileName}, file_hash=#{fileHash}, period=#{period},
    status=#{status}, total_rows=#{totalRows}, success_rows=#{successRows}, error_rows=#{errorRows},
    message=#{message}, created_by=#{createdBy}
WHERE id=#{id}
